L = require("leaflet")
upper_basin_geo  = FileAttachment("GIS_Data/UpperBasin_HUC2.geojson").json()
lower_basin_geo  = FileAttachment("GIS_Data/LowerBasin_HUC2.geojson").json()
reservoirs_geo   = FileAttachment("GIS_Data/Reservoirs.geojson").json()
rivers           = FileAttachment("GIS_Data/Colorado_River_Basin_Rivers.geojson").json()
{
  const div = html`&lt;div style="width:100%; height:700px;"&gt;&lt;/div&gt;`

  // Allow div to render before initializing map
  yield div

  const map = L.map(div, { 
    center: [36.5, -112], 
    zoom: 6 
  })

  // Basemap tile layer
  const tiles = L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "© OpenStreetMap contributors",
    maxZoom: 18
  }).addTo(map)

  // Upper Basin polygon layer
  const upper_basin_layer = L.geoJSON(upper_basin_geo, {
    style: {
      color: "#1a6496",
      weight: 2,
      fillColor: "#5bc0de",
      fillOpacity: 0.3
    }
  }).addTo(map)

  // Lower Basin polygon layer
  const lower_basin_layer = L.geoJSON(lower_basin_geo, {
    style: {
      color: "#a94442",
      weight: 2,
      fillColor: "#e06666",
      fillOpacity: 0.3
    }
  }).addTo(map)

  // Rivers
  const rivers_layer = L.geoJSON(rivers, {
    style: {
      color: "#006cfa",
      weight: 2
    }
  }).addTo(map)

  // Reservoir point layer
  const reservoirs_layer = L.geoJSON(reservoirs_geo, {
    // Custom marker style
    pointToLayer: (feature, latlng) =&gt; {
      // Color scaling
      const color_scale = pct =&gt; {
       if (pct &gt;= 70)      return "#198754"   // green  - above 70%
       else if (pct &gt;= 50) return "#ffc107"   // yellow - 50-70%
       else if (pct &gt;= 30) return "#fd7e14"   // orange - 30-50%
       else                return "#dc3545"   // red    - below 30%
       }
      const pct_full = feature.properties.Percent_Full_MAF ?? 0
      const capacity = feature.properties.Max_Capacity_MAF ?? 0
      const radius = Math.sqrt(capacity) * 5
      return L.circleMarker(latlng, {
        radius: radius,
        fillColor: color_scale(pct_full),
        color: "white",
        weight: 2,
        fillOpacity: 0.9
      })
    },
    onEachFeature: (feature, layer) =&gt; {
        const p = feature.properties

        const popup_html = `
            &lt;div style="width: 380px; font-family: sans-serif;"&gt;

            &lt;b style="font-size: 14px;"&gt;${p.Reservoir}: ${p.Date}&lt;/b&gt;
            &lt;hr style="margin: 6px 0; border-color: #dee2e6;"&gt;

            &lt;div style="display: flex; gap: 16px;"&gt;

                &lt;!-- Elevation column --&gt;
                &lt;div style="flex: 1;"&gt;
                &lt;div style="font-size: 11px; font-weight: 700; color: steelblue; 
                            text-transform: uppercase; margin-bottom: 6px;"&gt;
                    Elevation
                &lt;/div&gt;
                &lt;table style="width: 100%; font-size: 12px; border-collapse: collapse;"&gt;
                    &lt;tr style="border-bottom: 1px solid #dee2e6;"&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;Current&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Elevation ?? "N/A"} ft&lt;/td&gt;
                    &lt;/tr&gt;
                    &lt;tr style="border-bottom: 1px solid #dee2e6;"&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;1yr Ago&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Elv_1yr_Ago ?? "N/A"} ft&lt;/td&gt;
                    &lt;/tr&gt;
                    &lt;tr style="border-bottom: 1px solid #dee2e6;"&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;10yr Avg&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Elv_Day_Avg_10yr ?? "N/A"} ft&lt;/td&gt;
                    &lt;/tr&gt;
                    &lt;tr&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;30yr Avg&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Elv_Day_Avg_30yr ?? "N/A"} ft&lt;/td&gt;
                    &lt;/tr&gt;
                &lt;/table&gt;
                &lt;/div&gt;

                &lt;!-- Divider --&gt;
                &lt;div style="width: 1px; background: #dee2e6;"&gt;&lt;/div&gt;

                &lt;!-- Storage column --&gt;
                &lt;div style="flex: 1;"&gt;
                &lt;div style="font-size: 11px; font-weight: 700; color: steelblue;
                            text-transform: uppercase; margin-bottom: 6px;"&gt;
                    Storage
                &lt;/div&gt;
                &lt;table style="width: 100%; font-size: 12px; border-collapse: collapse;"&gt;
                    &lt;tr style="border-bottom: 1px solid #dee2e6;"&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;Current&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Storage_MAF ?? "N/A"} MAF | ${p.Percent_Full_MAF}%&lt;/td&gt;
                    &lt;/tr&gt;
                    &lt;tr style="border-bottom: 1px solid #dee2e6;"&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;1yr Ago&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.StorMAF_1yr_Ago ?? "N/A"} MAF&lt;/td&gt;
                    &lt;/tr&gt;
                    &lt;tr style="border-bottom: 1px solid #dee2e6;"&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;10yr Avg&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Stor_Day_Avg_10yr ?? "N/A"} MAF&lt;/td&gt;
                    &lt;/tr&gt;
                    &lt;tr&gt;
                    &lt;td style="padding: 4px 0; color: #6c757d;"&gt;30yr Avg&lt;/td&gt;
                    &lt;td style="padding: 4px 0; text-align: right; font-weight: 600;"&gt;${p.Stor_Day_Avg_30yr ?? "N/A"} MAF&lt;/td&gt;
                    &lt;/tr&gt;
                &lt;/table&gt;
                &lt;/div&gt;

            &lt;/div&gt;
            &lt;/div&gt;
        `

        layer.bindPopup(popup_html, { maxWidth: 400 })
        }
        }).addTo(map)

  // Layer control
  L.control.layers(
    {
      // Base layers - only one can be active at a time
      "OpenStreetMap": tiles
    },
    {
      // Overlay layers - each has its own checkbox
      "Upper Basin":  upper_basin_layer,
      "Lower Basin":  lower_basin_layer,
      "Reservoirs":   reservoirs_layer,
